def round_half_to_even(n):
    if not isinstance(n, (int, float)):
        raise TypeError("Argument must be a number")
    else:
        if n.is_integer():
            return int(n)
        else:
            # Convert n to a string and split it into integer and decimal parts
            n_str = str(n).split(".")
            n_int, n_dec = int(n_str[0]), int(n_str[1])

            # If the decimal part is exactly 0.5, round to the nearest even number
            if n_dec == 5:
                if n_int % 2 == 0:
                    return n_int
                else:
                    return n_int + 1
            # If the decimal part is less than 0.5, round down
            elif n_dec < 5:
                return n_int
            # If the decimal part is greater than 0.5, round up
            else:
                return n_int + 1

