def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """

    if not isinstance(coord, tuple):
        raise TypeError("Expected a tuple, got {0} instead".format(type(coord)))
    if len(coord) != self.dimension:
        raise ValueError("Coordinate tuple has incorrect length")
    if not all(isinstance(c, int) for c in coord):
        raise TypeError("Coordinate tuple must contain only integers")

    if weight < 0:
        raise ValueError("Weight must be non-negative")

    try:
        self.bins[coord] += weight
    except KeyError:
        pass

