def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    if not commands:
        raise ValueError("At least one command is required")

    if not isinstance(commands, (list, tuple)):
        commands = [commands]

    if not all(isinstance(command, str) for command in commands):
        raise ValueError("All commands must be non-empty strings")

    if not isinstance(args, (list, tuple)):
        args = [args]

    if not all(isinstance(arg, str) for arg in args):
        raise ValueError("All arguments must be non-empty strings")

    if cwd is not None and not isinstance(cwd, str):
        raise ValueError("cwd must be a string")

    if not isinstance(verbose, bool):
        raise ValueError("verbose must be a boolean")

    if not isinstance(hide_stderr, bool):
        raise ValueError("hide_stderr must be a boolean")

    if env is not None and not isinstance(env, dict):
        raise ValueError("env must be a dictionary")

    process = subprocess.Popen(
        commands,
        cwd=cwd,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE if hide_stderr else None,
        env=dict(os.environ, **env) if env is not None else None,
    )
    try:
        stdout, stderr = process.communicate(args, timeout=_TIMEOUT, verbose=verbose)
        if process.returncode != 0:
            raise subprocess.CalledProcessError(process.returncode, process.args)
        return stdout or None, stderr or None
    finally:
        process.kill()

