def next_version(version):
    # Check if version is a valid version number
    if not isinstance(version, str) or not version.isdigit():
        raise TypeError("Invalid version number")

    major, minor, patch = version.split(".")

    # First case: no leading zeroes
    if major.startswith("0") or minor.startswith("0") or patch.startswith("0"):
        major, minor, patch = map(int, (major, minor, patch))
        return f"{major+1}.{minor+1}.{patch+1}"

    # Second case: leading zeroes
    else:
        major, minor, patch = map(int, (major, minor, patch))
        return f"{major+1}.{minor+1}.{patch+1:03}"

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    for version_dir in version_dirs:
        if not os.path.isfile(os.path.join(version_dir, "inventory.yml")):
            raise Exception(f"No inventory found for version {version_dir}")

    root_inv_dict = parse_inventory(os.path.join(self.root_dir, "inventory.yml"))
    for version_dir in version_dirs:
        inv_dict = parse_inventory(os.path.join(version_dir, "inventory.yml"))
        version_content_digests = {}
