def paging(response, max_results):
    def get_next_page(get_next_page_gen):
        if get_next_page_gen is None:
            yield PagingObject(gen = get_next_page_gen)
        else:
            try:
                result = next(get_next_page_gen)
                yield PagingObject(result, get_next_page_gen)
            except StopIteration:
                return

    class PagingObject:
        def __init__(self, result, gen = None):
            self.result = result
            self.gen = gen

        # Python 3 only
        def __iter__(self):
            yield self.result
            if self.gen is not None:
                yield from self.gen

        def next(self):
            try:
                return next(self.gen)
            except StopIteration:
                raise StopIteration()

    page_size = max_results
    gen = itertools.groupby(response, lambda x: x)). This will enable us to page through the responses efficiently.
    return get_next_page(gen)

def size_to_bytes(size: str) -> int:
    bytes_suffix = {
        "B": 1,
        "K": 1024,
        "M": 1024**2,
        "G": 1024**3,
        "T": 1024**4,
        "P": 1024**5,
        "E": 1024**6,
        "Z": 1024**7,
        "Y": 1024**8,
    }

    size_num = size[:-1]
    size_unit = size[-1]

    try:
        return int(float(size_num) * bytes_suffix[size_unit])
    except KeyError:
        raise ValueError(f"Invalid suffix '{size_unit}'")
    except ValueError:
        raise ValueError(f"Invalid size string '{size}'")

