def verifyClass(iface, candidate, tentative=False):
    if not isinstance(candidate, iface):
        raise TypeError("candidate must be an instance of {}".format(iface.__name__))
    try:
        # Iterate over all methods in the iface and check if they are implemented in the candidate
        for name, method in iface.__dict__.items():
            if not isinstance(getattr(candidate, name, None), method.__class__):
                raise NotImplementedError("method {} is not implemented in {}".format(
                    name, candidate.__class__.__name__))
        # If the method is not a tentative one, check if the candidate is an instance of the iface
        if not tentative and not isinstance(candidate, iface):
            raise TypeError("candidate must be an instance of {}".format(iface.__name__))
    except AttributeError:
        raise TypeError("candidate must be an instance of {}".format(iface.__name__))
