    if not isinstance(timestr, str):
        raise TypeError("Invalid input type. Expected string, got {type(timestr)}")
    if default is not None and not isinstance(default, datetime.datetime):
        raise TypeError("Invalid input type. Expected datetime.datetime, got {type(default)}")
    if ignoretz and tzinfos is not None:
        raise ValueError("Invalid input. 'ignoretz' and 'tzinfos' cannot be used together.")

    # Parse the date/time string using the `_parse()` function
    dt, tokens = _parse(timestr, default, ignoretz, tzinfos, **kwargs)

    # Validate the date and time
    if not isinstance(dt, datetime.datetime):
        raise ValueError("Invalid datetime object returned from _parse().")
    if dt.year < 1 or dt.year > 9999:
        raise ValueError("Invalid year in datetime object.")
    if dt.month < 1 or dt.month > 12:
        raise ValueError("Invalid month in datetime object.")
    if dt.day < 1 or dt.day > 31:
        raise ValueError("Invalid day in datetime object.")
    if dt.hour < 0 or dt.hour > 23:
        raise ValueError("Invalid hour in datetime object.")
    if dt.minute < 0 or dt.minute > 59:
        raise ValueError("Invalid minute in datetime object.")
    if dt.second < 0 or dt.second > 59:
        raise ValueError("Invalid second in datetime object.")
    if dt.microsecond < 0 or dt.microsecond > 999999:
        raise ValueError("Invalid microsecond in datetime object.")
    if dt.tzinfo is not None and not isinstance(dt.tzinfo, datetime.tzinfo):
        raise ValueError("Invalid tzinfo in datetime object.")

    # Return the parsed datetime object
    return dt

