def identify_request(request: RequestType):
    # Check if the request is a public message
    if request["type"] == "public_message":
        # Check if the request is a legacy payload
        if "legacy" in request:
            return "legacy_payload"
        else:
            return "public_message"
    # Check if the request is a private message
    elif request["type"] == "private_message":
        return "private_message"
    # If the request is none of the above, raise an error
    else:
        err_msg = f"Invalid request type: {request['type']}"
        raise ValueError(err_msg)

