def find_tags(text: str, replacer: callable = None) -> Tuple[Set[str], str]:
    tags = set()
    block = False
    output = text
    for word in text.split():
        if word == "`:":
            block = True
            continue
        if word == ":]":
            block = False
            continue
        if block or word[0] != "#":
            continue
        tags.add(word[1:])
        if replacer is not None:
            output = output.replace(word, replacer(word))
    return tags, output

