def verify_relayable_signature(public_key, doc, signature):
    try:
        # Retrieve the XML signature from the document
        xml_signature = doc.find("Signature")
        if xml_signature is None:
            raise ValueError("Missing XML signature in the document")

        # Load the public key and the signature
        public_key = serialization.load_pem_public_key(public_key)
        signature = serialization.load_der_signature(signature)

        # Check that the signature is authentic
        if not signature.verify(xml_signature, public_key):
            raise ValueError("XML signature is not authentic")

        return True
    except (ValueError, TypeError) as e:
        raise ValueError("Failed to verify the XML signature") from e

