        error = Exception("Unknown error occurred")
    return status, error

def dict_insert(dic, val, key, *keys):
    if not dic:
        raise ValueError("Dictionary cannot be empty")
    if not key:
        raise ValueError("Key cannot be empty")
    current_key = keys[0]
    if not current_key:
        raise ValueError("Sub key cannot be empty")
    if current_key not in dic:
        dic[current_key] = {}
    if len(keys) == 1:
        dic[key][current_key] = val
    else:
        dict_insert(dic[key], val, current_key, *keys[1:])

